import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import Tilt from "react-parallax-tilt";
import "./lavori.css";
import chiste from "../image/chiste.PNG";
import dan from "../image/dan.PNG";
import roccia from "../image/roccia.PNG";

const lavori = [
  {
    title: "Ristorante Chistè Trento",
    description: "Un progetto CMS da zero, con libertà stilistica, responsive, alta presenza di PHP per un gestionale menù, un form di contatto e di prenotazioni online e SEO base.",
    image: chiste,
  },
  {
    title: "Danilo Custom Case",
    description: "Sito web responsive creato con HTML, CSS, e JavaScript. Un alternativa economica a un E-Commerce vero e proprio. Grande libertà stilistica e basso budget.",
    image: dan,
  },
  {
    title: "Ristorante LaRoccia Trento",
    description: "Restyling di un sito di un ristorante tramite wordpress e l'utlizzo di html, css e javascript. Libertà stilistica limitata. Correzione della SEO.",
    image: roccia,
  },
];

function Lavori() {
  const [showMore, setShowMore] = useState(false);
  const [showMessage, setShowMessage] = useState(false);

  useEffect(() => {
    if (showMore) {
      const timer = setTimeout(() => {
        setShowMessage(true);
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, [showMore]);

  return (
    <section className="lavori-section">
      <h2 className="lavori-title">🔨 I miei Lavori</h2>
      <div className="lavori-grid">
        {lavori.map((lavoro, index) => (
          <motion.div
            key={index}
            initial={{ opacity: 0, y: 40 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: index * 0.2 }}
            viewport={{ once: true }}
          >
            <Tilt
              tiltMaxAngleX={10}
              tiltMaxAngleY={10}
              glareEnable={true}
              glareColor="#14b8a6"
              glareMaxOpacity={0.2}
            >
              <div className="lavoro-card glass">
                <img
                  src={lavoro.image}
                  alt={lavoro.title}
                  className="lavoro-image"
                />
                <div className="lavoro-content">
                  <h3 className="lavoro-title">{lavoro.title}</h3>
                  <p className="lavoro-description">{lavoro.description}</p>
                </div>
              </div>
            </Tilt>
          </motion.div>
        ))}
      </div>

      {!showMore && (
        <motion.button
          className="show-more"
          onClick={() => setShowMore(true)}
          whileHover={{ scale: 1.1 }}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.5 }}
        >
          Scopri altri lavori
        </motion.button>
      )}

      {showMore && !showMessage && (
        <div className="dots-container">
          <span className="dot"></span>
          <span className="dot"></span>
          <span className="dot"></span>
        </div>
      )}

      {showMessage && (
        <motion.p
          className="coming-soon"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 1 }}
        >
          ✨ Presto altri lavori!
        </motion.p>
      )}
    </section>
  );
}

export default Lavori;
