import React, { useRef, useEffect, useState } from "react";
import * as THREE from "three";
import FOG from "vanta/dist/vanta.fog.min"; // importa direttamente il tipo di Vanta
import "./hero.css";

function Hero() {
  const vantaRef = useRef(null);
  const [vantaEffect, setVantaEffect] = useState(null);

  useEffect(() => {
    if (!vantaEffect) {
      setVantaEffect(
        FOG({
          el: vantaRef.current,
          THREE: THREE, // passa la libreria importata
          mouseControls: true,
          touchControls: true,
          gyroControls: false,
          minHeight: 200.0,
          minWidth: 200.0,
          highlightColor: 0x91bbc5,
          midtoneColor: 0x0,
          lowlightColor: 0x324293,
          baseColor: 0x0,
        })
      );
    }

    return () => {
      if (vantaEffect) vantaEffect.destroy();
    };
  }, [vantaEffect]);

  return (
    <section
      className="hero-section text-light d-flex align-items-center"
      ref={vantaRef}
    >
      <div className="container text-center">
        <h1 className="hero-title">
          Ciao, sono <span className="text-info">Andrea Schwarz</span>
        </h1>
        <p className="lead text-light mb-4">
          Sviluppatore Web <span className="text-info">•</span> Web Designer{" "}
          <span className="text-info">•</span> UX Designer
        </p>
        <a
          href="#progetti"
          className="btn btn-outline-info btn-lg px-5 py-3 fw-semibold hero-btn"
        >
          Scopri i miei progetti
        </a>
      </div>

      <div className="scroll-down-arrow">
        <svg
          width="40"
          height="40"
          viewBox="0 0 24 24"
          fill="none"
          stroke="#0dcaf0"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          className="arrow-icon"
        >
          <line x1="12" y1="5" x2="12" y2="19" />
          <polyline points="19 12 12 19 5 12" />
        </svg>
      </div>
    </section>
  );
}

export default Hero;
