import React from "react";
import { FaInstagram, FaLinkedin, FaEnvelope } from "react-icons/fa";
import "./footer.css";

function Footer() {
  return (
    <footer className="footer">
      <div className="footer-content">
        <div className="footer-heading">
          <span className="emoji">🌐</span>
          <h3 className="footer-title">Seguimi</h3>
        </div>
        <div className="footer-icons">
          <a href="https://github.com/tuo-username" target="_blank" rel="noopener noreferrer">
            <FaInstagram />
          </a>
          <a href="https://linkedin.com/in/tuo-username" target="_blank" rel="noopener noreferrer">
            <FaLinkedin />
          </a>
          <a href="mailto:tuamail@example.com">
            <FaEnvelope />
          </a>
        </div>
        <p className="footer-text">© {new Date().getFullYear()} Tutti i diritti riservati. Sito creato con 🖤</p>
      </div>
    </footer>
  );
}

export default Footer;
