import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import "./pricing.css";

const options = [
  {
    label: "Sito base",
    subtitle: "Sito vetrina con una singola pagina",
    price: 300,
    features: ["1 pagina", "Responsive", "Contatti", "Design semplice"],
    extra: "Perfetto per chi vuole una presenza online minimale ma professionale.",
  },
  {
    label: "Sito intermedio",
    subtitle: "Sito da 3 a 5 pagine con contenuti dettagliati",
    price: 600,
    features: ["Home, Servizi, Chi siamo, Contatti", "SEO base", "Design personalizzato"],
    extra: "Ideale per aziende o liberi professionisti con più servizi da promuovere.",
  },
  {
    label: "Sito avanzato",
    subtitle: "Sito con CMS integrato per gestire contenuti",
    price: 900,
    features: ["CMS (WordPress o simile)", "Blog incluso", "Aggiornabile da te"],
    extra: "Pensato per chi vuole gestire i contenuti in autonomia senza competenze tecniche.",
  },
  {
    label: "E-commerce base",
    subtitle: "Negozio online fino a 20 prodotti",
    price: 1200,
    features: ["Carrello e checkout", "Gestione prodotti", "Responsive"],
    extra: "Ottimo per piccoli business che vogliono vendere online in modo efficace.",
  },
];

function PrezzoIndicativo() {
  const [selectedLabel, setSelectedLabel] = useState(null);

  return (
    <div className="pricing-section">
      <h2 className="pricing-title">💡 Seleziona il tipo di sito</h2>
      <div className="pricing-grid">
        {options.map((opt, idx) => {
          const isSelected = selectedLabel === opt.label;
          return (
            <motion.div
              key={idx}
              layout
              onClick={() =>
                setSelectedLabel(isSelected ? null : opt.label)
              }
              className={`pricing-card ${isSelected ? "expanded" : ""}`}
              transition={{ layout: { duration: 0.4, type: "spring" } }}
            >
              <div className="card-main">
                <h3 className="card-title">{opt.label}</h3>
                <p className="card-subtitle">{opt.subtitle}</p>
                <ul className="card-features">
                  {opt.features.map((feat, i) => (
                    <li key={i}>🔵 {feat}</li>
                  ))}
                </ul>
                <div className="card-price">A partire da €{opt.price}</div>
              </div>

              <AnimatePresence>
                {isSelected && (
                  <motion.div
                    initial={{ opacity: 0, height: 0 }}
                    animate={{ opacity: 1, height: "auto" }}
                    exit={{ opacity: 0, height: 0 }}
                    className="card-extra"
                  >
                    <p className="extra-text">{opt.extra}</p>
                    <motion.a
                      href="#contatti"
                      className="contact-button"
                      initial={{ opacity: 0, y: 10 }}
                      animate={{ opacity: 1, y: 0 }}
                    >
                      Contattami
                    </motion.a>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          );
        })}
      </div>
    </div>
  );
}

export default PrezzoIndicativo;
