import React from "react";
import { motion } from "framer-motion";
import "./chisono.css";

function ChiSono() {
  return (
    <section className="about-section">
      <div className="about-container">
        <motion.h2
          className="about-title"
          initial={{ opacity: 0, y: 40 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1 }}
        >
          Ciao! Sono <span className="highlight">Andrea Schwarz</span>
        </motion.h2>
        <motion.p
          className="about-text"
          initial={{ opacity: 0, x: -40 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 1, delay: 0.2 }}
        >
          Studio <strong>Ingegneria Informatica</strong> all’Università di Trento,
          dove unisco logica, passione e creatività per dare vita a soluzioni digitali moderne.
        </motion.p>
        <motion.p
          className="about-text"
          initial={{ opacity: 0, x: -40 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 1, delay: 0.4 }}
        >
          Sono uno <strong>sviluppatore web</strong> con un occhio attento al design,
          amante delle UI pulite e delle performance elevate.
        </motion.p>
        <motion.p
          className="about-text"
          initial={{ opacity: 0, x: -40 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 1, delay: 0.6 }}
        >
          Mi piace lavorare con <span className="tech-list">React, JavaScript, CSS3, Git</span> e
          scoprire costantemente nuove tecnologie per migliorare.
        </motion.p>
        <motion.p
          className="about-text emphasis"
          initial={{ opacity: 0, y: 40 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1, delay: 0.8 }}
        >
          Il mio obiettivo? <em>Costruire esperienze web memorabili e funzionali</em>.
        </motion.p>
      </div>
    </section>
  );
}

export default ChiSono;
